const dsl = `workspace "Parcel Tracker" "A C4 model of the parcel delivery tracking platform." {
    properties {
        scope = "SoftwareSystem"
    }

    !docs
    # Parcel Tracker
    A platform for tracking parcel deliveries, owned and operated by our company. Customers look up the status of their parcels through the web portal, and the dispatch service assigns parcels to couriers.

    !decisions
    # Shared Pricing Rules Library
    Both the web portal and the dispatch service embed a shared pricing rules library that computes delivery prices from weight and zone, so pricing logic is defined once and reused.

    model {
        customer = person "Customer" "Looks up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "A platform for tracking parcel deliveries, owned and operated by our company." {
            webPortal = container "Web Portal" "Where customers look up the status of their shipments." "Web Application"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers." "Service"
            database = container "Database" "Stores shipments and dispatch records." "Database"
            pricingLibrary = container "Pricing Rules Library" "Computes delivery prices from weight and zone." "Shared Library" "Library"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "Delivers customer notification emails. Operated by a different organization." "External"

        customer -> webPortal "looks up the status of their parcels" "Web"
        webPortal -> database "reads shipment records from" "SQL"
        dispatchService -> database "writes dispatch records to" "SQL"
        dispatchService -> emailProvider "sends customer notification emails to" "REST/JSON"
        webPortal -> pricingLibrary "embeds" "Embedded"
        dispatchService -> pricingLibrary "embeds" "Embedded"
    }

    views {
        systemContext parcelTracker "SystemContext" "A system context diagram of the Parcel Tracker." {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "A container diagram of the Parcel Tracker." {
            include *
            autoLayout
        }
    }
}`;
